-- Economics Gen2 T5 Practice rebalancing: 20 easy / 30 medium / 20 hard.
-- Original questions never deleted; originals with historical references remain resolvable.
-- New question versions carry their own complete trilingual content and per-option diagnostics.
-- Preconditions and postconditions are enforced transactionally. Run controlled QA transaction first.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '90s';
DO $reb$
DECLARE
  payload jsonb := '[{"ref":"EC9708:G2:EC9708-G2-T5-P-027","d":"hard","sec":195,"k":"C","en":"A government pays a $200 grant to each applicant claiming it plans to adopt a cleaner process. Of 100 applicants, 70 would have adopted without support; the grant induces 20 additional factories to adopt, while 10 recipients still fail to adopt. Every applicant receives the grant and administration costs $2,000. What is total public spending per additional adopting factory?","ru":"Государство выплачивает по $200 каждому из 100 заводов, заявивших о намерении внедрить экологичную технологию. Из них 70 внедрили бы её и без субсидии, ещё 20 внедряют благодаря субсидии, а 10 так и не внедряют. Выплаты получают все заявители; администрирование стоит $2 000. Каковы общие бюджетные затраты на один дополнительно внедривший завод?","uz":"Davlat ekologik texnologiyani joriy etishni rejalaganini bildirgan 100 zavodning har biriga $200 grant beradi. Ulardan 70 tasi grantsiz ham joriy etgan bo‘lardi, yana 20 tasi grant tufayli joriy etadi, 10 tasi esa joriy etmaydi. Barcha arizachilar grant oladi; boshqaruv xarajati $2000. Grant tufayli qo‘shimcha texnologiya joriy etgan bitta zavodga jami davlat xarajati qancha?","options_en":["$200","$220","$1,100","$2,200"],"options_ru":["$200","$220","$1 100","$2 200"],"options_uz":["$200","$220","$1100","$2200"],"why":["Grants cost 100×$200=$20,000 plus $2,000 administration. Only 20 adoptions are additional; $22,000/20=$1,100 per extra adoption. The programme has substantial deadweight spending.","Гранты обходятся в $20 000 плюс $2 000 администрирования. Дополнительных внедрений только 20; $22 000/20=$1 100 за каждое. Большая часть расходов не меняет поведение.","Grantlar 100×$200=$20 000, boshqaruv $2000. Qo‘shimcha joriy etishlar 20 ta; $22 000/20=$1100. Xarajatlarning katta qismi qarorga ta’sir qilmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-029","d":"hard","sec":195,"k":"B","en":"A factory can install a filter for $80 per week. Without it, downstream households suffer verified harm of $140 per week. Installing the filter does not alter output. With zero bargaining costs and enforceable rights, what is the maximum net social gain from installing it, and which conclusion follows?","ru":"Завод может установить фильтр за $80 в неделю. Без фильтра жители ниже по течению несут подтверждённый ущерб $140 в неделю. Фильтр не влияет на выпуск. При нулевых издержках переговоров и защищённых правах какова максимальная чистая общественная выгода установки и какой вывод следует?","uz":"Zavod haftasiga $80 ga filtr o‘rnata oladi. Filtrsiz quyi oqimdagi aholi haftasiga $140 zarar ko‘radi. Filtr ishlab chiqarishni o‘zgartirmaydi. Muzokara xarajati nol va huquqlar kafolatlangan bo‘lsa, filtrning eng katta sof ijtimoiy foydasi qancha va qanday xulosa kelib chiqadi?","options_en":["$140; production must shut down","$60; bargaining could support filtering, although compensation depends on rights","$80; residents must always pay the full filter cost","−$60; it is efficient to continue polluting"],"options_ru":["$140; производство необходимо остановить","$60; переговоры могут обеспечить установку, но компенсации зависят от прав","$80; жители всегда должны полностью оплатить фильтр","−$60; выгоднее продолжать загрязнение"],"options_uz":["$140; ishlab chiqarish albatta to‘xtashi kerak","$60; muzokara filtrga olib kelishi mumkin, lekin to‘lov huquqlarga bog‘liq","$80; aholi har doim filtrni to‘liq to‘lashi kerak","−$60; ifloslantirishni davom ettirish samarali"],"why":["Avoiding $140 harm at a cost of $80 creates $60 net gain. Bargaining can support the efficient outcome under the stated assumptions, but rights affect who compensates whom.","Предотвращение ущерба $140 при затратах $80 даёт $60 чистой выгоды. Переговоры могут привести к эффективному решению, однако распределение платежей зависит от прав.","$140 zararni $80 xarajat bilan oldini olish $60 sof foyda beradi. Kelishuv samarali natijaga olib kelishi mumkin, ammo kim to‘lashi mulk huquqlariga bog‘liq."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-032","d":"hard","sec":190,"k":"D","en":"A competitive employer receives marginal revenue products of $90, $75, $60 and $45 from four additional workers in sequence. Initially the daily wage is $65; later it rises to $80, with MRP unchanged. How many of these workers maximise profit before and after the wage rise?","ru":"Для конкурентного работодателя предельная доходность четырёх дополнительных работников по порядку составляет $90, $75, $60 и $45 в день. Первоначальная дневная зарплата $65, позже она растёт до $80; MRP не меняется. Сколько этих работников выгодно нанять до и после повышения зарплаты?","uz":"Raqobatli ish beruvchi ketma-ket qo‘shimcha to‘rt ishchidan kuniga $90, $75, $60 va $45 chegaraviy daromad oladi. Dastlab kunlik ish haqi $65, keyin $80 ga oshadi; MRP o‘zgarmaydi. Ish haqi o‘sishidan oldin va keyin nechtasini yollash foydani maksimallashtiradi?","options_en":["3 before; 2 after","2 before; 2 after","1 before; 2 after","2 before; 1 after"],"options_ru":["До повышения — 3; после — 2","До повышения — 2; после — 2","До повышения — 1; после — 2","До повышения — 2; после — 1"],"options_uz":["Oldin — 3; keyin — 2","Oldin — 2; keyin — 2","Oldin — 1; keyin — 2","Oldin — 2; keyin — 1"],"why":["At wage $65, only MRPs $90 and $75 exceed cost, so hire 2. At $80, only $90 exceeds cost, so hire 1.","При зарплате $65 выгодны работники с MRP $90 и $75 — двое. При $80 выгоден лишь первый — один.","$65 ish haqida $90 va $75 MRPlar xarajatdan yuqori, 2 kishi yollanadi. $80 da faqat $90 yuqori, 1 kishi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-033","d":"hard","sec":195,"k":"C","en":"Two households earn $12,000 and $90,000 annually before redistribution. The lower-income household receives a $5,000 means-tested transfer, while the higher-income household pays an additional $25,000 income tax. Ignore responses and other taxes. By how much does their disposable-income gap narrow, and is the lower-income household necessarily above a $20,000 poverty threshold?","ru":"До перераспределения два домохозяйства зарабатывают $12 000 и $90 000 в год. Первое получает адресный трансферт $5 000, второе платит дополнительный подоходный налог $25 000. Игнорируйте поведенческие эффекты и другие налоги. На сколько сократится разница располагаемых доходов и обязательно ли первое домохозяйство выйдет за порог бедности $20 000?","uz":"Qayta taqsimlashdan oldin ikki xonadon yillik $12 000 va $90 000 topadi. Kam daromadlisi $5000 maqsadli transfert oladi, yuqori daromadlisi qo‘shimcha $25 000 daromad solig‘i to‘laydi. Boshqa ta’sir va soliqlarni hisoblamang. Ixtiyordagi daromad farqi qanchaga qisqaradi va past daromadli xonadon $20 000 kambag‘allik chegarasidan albatta chiqadimi?","options_en":["Gap narrows by $25,000; yes, income becomes $37,000","Gap narrows by $30,000; yes, income reaches $20,000","Gap narrows by $30,000; no, lower income is still $17,000","Gap widens by $30,000; no, income stays $12,000"],"options_ru":["Разрыв сокращается на $25 000; да, доход станет $37 000","Разрыв сокращается на $30 000; да, доход достигнет $20 000","Разрыв сокращается на $30 000; нет, доход первого всё ещё $17 000","Разрыв увеличивается на $30 000; нет, доход остаётся $12 000"],"options_uz":["Farq $25 000 ga kamayadi; ha, daromad $37 000 bo‘ladi","Farq $30 000 ga kamayadi; ha, daromad $20 000 ga yetadi","Farq $30 000 ga kamayadi; yo‘q, past daromad $17 000 bo‘ladi","Farq $30 000 ga oshadi; yo‘q, daromad $12 000 qoladi"],"why":["Original gap =90,000−12,000=$78,000. After redistribution it is 65,000−17,000=$48,000, $30,000 less. $17,000 remains below $20,000.","Изначальный разрыв $78 000; после мер доходы $65 000 и $17 000, разрыв $48 000. Сокращение $30 000, но $17 000 ниже порога бедности.","Dastlab farq $78 000; keyin daromadlar $65 000 va $17 000, farq $48 000. $30 000 ga qisqaradi, ammo $17 000 kambag‘allik chegarasidan past."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-037","d":"hard","sec":195,"k":"A","en":"An additional vaccination has private benefit $35, external benefit $25 and marginal provision cost $50. Families perceive the private benefit correctly but ignore the benefit to others. Which assessment of a $20 per-vaccination subsidy is supported at this margin?","ru":"Дополнительная вакцинация даёт личную выгоду $35, внешнюю выгоду $25 и обходится в $50. Семьи правильно оценивают личную выгоду, но не учитывают пользу другим. Как оценить субсидию $20 на прививку на данном пределе?","uz":"Qo‘shimcha emlashning shaxsiy foydasi $35, tashqi foydasi $25, taqdim etish xarajati $50. Oilalar shaxsiy foydani to‘g‘ri, boshqalarga foydani esa hisobga olmaydi. Shu chegaradagi har bir emlashga $20 subsidiya haqida qanday xulosa asosli?","options_en":["It can make private uptake attractive and the unit has $10 net social benefit, although $20 is below the full external benefit","It eliminates the external benefit and makes net social benefit zero","It is unnecessary because private benefit already exceeds full cost","It creates $25 of net social loss regardless of behavioural response"],"options_ru":["Она может стимулировать личный спрос; чистая общественная выгода единицы $10, хотя $15 меньше внешней выгоды","Она устраняет внешнюю выгоду, делая чистую общественную выгоду нулевой","Она не нужна, поскольку личная выгода уже выше полных затрат","Она создаёт $25 общественного убытка независимо от реакции людей"],"options_uz":["U xususiy talabni rag‘batlantirishi mumkin; sof ijtimoiy foyda $10, garchi $20 tashqi foydadan kam","U tashqi foydani yo‘qotib, sof ijtimoiy foydani nol qiladi","Keraksiz, chunki shaxsiy foyda xarajatdan yuqori","Javob qanday bo‘lishidan qat’i nazar $25 ijtimoiy zarar yaratadi"],"why":["Total marginal social benefit=$35+$25=$60, cost=$50, so net social gain is $10. A $20 subsidy reduces the private payment to $30, below the $35 private benefit; the full external-benefit benchmark would be $25.","Общественная выгода $35+$25=$60 при затратах $50, чистая выгода $10. Субсидия $20 уменьшает личный платёж до $30, ниже личной выгоды $35; полная компенсация внешней выгоды соответствовала бы $25.","Jami ijtimoiy foyda $35+$25=$60, xarajat $50, sof foyda $10. $20 subsidiya shaxsiy to‘lovni $30 ga tushiradi, bu $35 foydadan past; tashqi foydani to‘liq qoplash me’yori $25."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-040","d":"hard","sec":195,"k":"B","en":"A firm''s marginal revenue from each extra unit of output is $12. The next three workers would add 6, 4 and 3 units of output respectively, with other inputs unchanged. Each worker costs $50 per day. How many of these workers should it hire, and what is the combined additional profit?","ru":"Предельный доход фирмы от каждой дополнительной единицы выпуска — $12. Следующие три работника прибавят соответственно 6, 4 и 3 единицы при неизменных остальных ресурсах. Каждый работник обходится в $50 в день. Сколько работников выгодно нанять и каков суммарный прирост прибыли?","uz":"Firma har qo‘shimcha mahsulot birligidan $12 chegaraviy daromad oladi. Keyingi uch ishchi mos ravishda 6, 4 va 3 birlik qo‘shadi, boshqa resurslar o‘zgarmaydi. Har ishchi kuniga $50 turadi. Nechtasini yollash foydali va jami qo‘shimcha foyda qancha?","options_en":["2 workers; +$20","1 worker; +$22","3 workers; +$56","1 worker; +$72"],"options_ru":["2 работника; +$20","1 работник; +$22","3 работника; +$56","1 работник; +$72"],"options_uz":["2 ishchi; +$20","1 ishchi; +$22","3 ishchi; +$56","1 ishchi; +$72"],"why":["Workers'' MRPs are 6×12=$72, 4×12=$48 and 3×12=$36. At $50 wage only the first is profitable, adding $22.","MRP работников равны $72, $48 и $36. При зарплате $50 выгоден только первый; его вклад в прибыль $72−$50=$22.","Ishchilar MRPlari $72, $48 va $36. $50 ish haqida faqat birinchi ishchi foydali; qo‘shimcha foyda $22."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-041","d":"hard","sec":175,"k":"D","en":"Households initially underestimate the private lifetime savings from insulation as $30, when independent tests estimate $80. Installation costs $60, and neighbouring households gain no measurable external benefit. Which policy explanation best fits public information disclosure?","ru":"Домохозяйства первоначально оценивают будущую личную экономию от утепления жилья в $30, хотя независимые испытания показывают $80. Установка обходится в $60, измеримых внешних выгод соседям нет. Какое объяснение политики раскрытия информации наиболее точное?","uz":"Xonadonlar issiqlik izolyatsiyasidan keladigan kelajakdagi shaxsiy tejamni $30 deb o‘ylaydi, mustaqil sinovlar esa $80 ekanini ko‘rsatadi. O‘rnatish xarajati $60, qo‘shnilarga o‘lchanadigan tashqi foyda yo‘q. Axborotni oshkor qilish siyosatini qaysi izoh eng to‘g‘ri tushuntiradi?","options_en":["It must address a $50 negative externality imposed on neighbours","It cannot alter demand because installation cost stays $60","It turns insulation into a non-rival public good","It can correct underestimated private benefits, changing a privately unattractive purchase into a beneficial one without proving an externality"],"options_ru":["Оно обязательно устраняет внешний ущерб соседям $50","Оно не влияет на спрос, поскольку цена установки остаётся $60","Оно превращает утепление в неисключаемое общественное благо","Оно исправляет недооценку личной выгоды и может сделать покупку выгодной без доказательства внешнего эффекта"],"options_uz":["U qo‘shnilarga $50 tashqi zararni bartaraf etishi shart","O‘rnatish $60 bo‘lgani uchun talabga ta’sir qilmaydi","Izolyatsiyani raqobatsiz jamoat ne’matiga aylantiradi","U shaxsiy foydani past baholashni tuzatadi va tashqi ta’sirsiz ham xaridni foydali qilishi mumkin"],"why":["Perceived private gain $30 is less than cost $60, whereas actual expected private gain $80 exceeds cost. This is an information problem, not proof of an externality.","Ошибочно воспринимаемая личная выгода $30 ниже затрат $60, фактическая ожидаемая выгода $80 выше затрат. Это информационная проблема, а не доказательство внешнего эффекта.","Baholangan shaxsiy foyda $30 xarajat $60 dan past, haqiqiy kutilgan foyda $80 esa yuqori. Bu tashqi ta’sir emas, axborot muammosi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-043","d":"hard","sec":185,"k":"C","en":"A city is choosing a bus-service concession. Operator A would cost taxpayers $100,000 annually but is expected to impose $80,000 in passenger-delay costs. Operator B would cost $140,000, cause only $20,000 in delay costs, and require an additional $10,000 in monitoring. Assume all costs are comparable and service coverage is equal. Which contract has the lower total social cost, and by how much?","ru":"Город выбирает концессию автобусного обслуживания. Оператор A обходится бюджету в $100 000 в год, но ожидаемые задержки пассажиров стоят обществу ещё $80 000. Оператор B стоит $140 000, задержки — $20 000, а дополнительный контроль — $10 000. Все оценки сопоставимы, охват одинаков. Какой контракт имеет меньшие совокупные общественные затраты и на сколько?","uz":"Shahar avtobus xizmati uchun shartnoma tanlaydi. A operatori davlatga yiliga $100 000 turadi, lekin yo‘lovchilar kechikishining kutilgan ijtimoiy qiymati $80 000. B operatori $140 000, kechikish $20 000 va qo‘shimcha nazorat $10 000 turadi. Xarajatlar taqqoslanadi, qamrov bir xil. Qaysi shartnomaning jami ijtimoiy xarajati kam va qancha?","options_en":["Operator A by $40,000, because only the public subsidy matters","Both cost exactly $180,000 when all effects are counted","Operator B by $10,000, once passenger delay and monitoring costs are included","Operator B by $80,000, because its delay costs are zero"],"options_ru":["Оператор A на $40 000, поскольку важны только бюджетные расходы","Оба стоят ровно $180 000 с учётом всех эффектов","Оператор B на $10 000 после учёта задержек и контроля","Оператор B на $80 000, поскольку задержек у него нет"],"options_uz":["Faqat davlat to‘lovi muhim bo‘lgani uchun A $40 000 arzon","Barcha ta’sirlarni hisoblaganda ikkalasi $180 000 turadi","Kechikish va nazorat qo‘shilsa, B operatori $10 000 arzon","B operatori $80 000 arzon, chunki unda kechikish yo‘q"],"why":["Total social cost A = $100,000+$80,000=$180,000. B = $140,000+$20,000+$10,000=$170,000, or $10,000 less. Lowest public bid need not be socially cheapest.","Общественные затраты A: $100 000+$80 000=$180 000. У B: $140 000+$20 000+$10 000=$170 000, на $10 000 меньше. Самая дешёвая бюджетная заявка не всегда социально оптимальна.","A jami xarajati $100 000+$80 000=$180 000. B jami $140 000+$20 000+$10 000=$170 000, $10 000 kam. Eng arzon davlat taklifi har doim jamiyat uchun arzon emas."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-045","d":"hard","sec":190,"k":"A","en":"A consultant increases her hourly wage from $50 to $60 but chooses to work 36 rather than 40 hours weekly. Assume there is no other income or job change. What happens to weekly earnings, and what labour-supply explanation is consistent with fewer hours at the higher wage?","ru":"Почасовая оплата консультанта выросла с $50 до $60, однако она сократила рабочую неделю с 40 до 36 часов. Другие доходы и условия не изменились. Что происходит с недельным заработком и каким эффектом предложения труда объясняется сокращение часов при более высокой ставке?","uz":"Maslahatchining soatlik ish haqi $50 dan $60 ga oshdi, ammo haftalik ish vaqtini 40 dan 36 soatga kamaytirdi. Boshqa daromad va ish shartlari o‘zgarmaydi. Haftalik daromad qanday o‘zgaradi va yuqori ish haqida ish vaqtining qisqarishi nimadan kelib chiqishi mumkin?","options_en":["Earnings rise $160; income effect can outweigh substitution effect","Earnings fall $160; substitution effect must dominate","Earnings rise $400; labour supply must always slope upward","Earnings remain $2,000; preferences are unchanged"],"options_ru":["Заработок растёт на $160; эффект дохода может превысить эффект замещения","Заработок падает на $160; обязательно доминирует эффект замещения","Заработок растёт на $400; предложение труда всегда возрастает","Заработок остаётся $2 000; предпочтения неизменны"],"options_uz":["Daromad $160 ga oshadi; daromad ta’siri almashtirish ta’siridan kuchli bo‘lishi mumkin","Daromad $160 ga tushadi; almashtirish ta’siri ustun","Daromad $400 ga oshadi; mehnat taklifi doim o‘sadi","Daromad $2000 bo‘lib qoladi; afzalliklar o‘zgarmaydi"],"why":["Weekly earnings go from 50×40=$2,000 to 60×36=$2,160, increasing $160. Fewer hours despite higher pay are consistent with a dominant income effect.","Недельный доход растёт с $2 000 до $2 160, на $160. Снижение часов при более высокой ставке согласуется с преобладанием эффекта дохода.","Haftalik daromad $2000 dan $2160 ga, ya’ni $160 oshadi. Yuqori ish haqida soatning kamayishi daromad ta’siri ustunligiga mos."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-046","d":"hard","sec":180,"k":"B","en":"A privately owned utility reduces annual operating costs from $5m to $4m after privatisation, but annual consumer bills rise from $7m to $9m, with the same number and quality of services. Which evaluation is most defensible?","ru":"После приватизации коммунальная компания снизила годовые операционные затраты с $5 млн до $4 млн, но общая сумма счетов потребителей выросла с $7 млн до $9 млн при прежнем количестве и качестве услуг. Какая оценка наиболее обоснованна?","uz":"Kommunal korxona xususiylashtirilgach yillik ishlash xarajati $5 mln dan $4 mln ga tushdi, ammo xizmat soni va sifati o‘zgarmagan holda iste’molchi to‘lovlari $7 mln dan $9 mln ga oshdi. Qaysi baho eng asosli?","options_en":["Privatisation certainly reduced consumer welfare and raised production costs","Operating efficiency improved, but higher bills raise distribution and market-power concerns; ownership alone does not settle welfare","The increase in bills proves that the firm became less cost-efficient","Competition is guaranteed because ownership changed"],"options_ru":["Приватизация обязательно ухудшила благосостояние и повысила производственные затраты","Операционная эффективность выросла, но повышение счетов вызывает вопросы распределения и рыночной власти; одна смена владельца не определяет благосостояние","Рост счетов доказывает снижение эффективности производства","Смена собственности гарантирует конкуренцию"],"options_uz":["Xususiylashtirish farovonlikni albatta yomonlashtirib, ishlab chiqarish xarajatini oshirdi","Operatsion samaradorlik oshdi, ammo yuqori to‘lovlar taqsimot va bozor kuchi muammosini tug‘diradi; faqat mulk shakli yetarli emas","To‘lovning oshishi ishlab chiqarish samarasizligini isbotlaydi","Mulk o‘zgarishi raqobatni kafolatlaydi"],"why":["Production costs fell $1m for the same output, consistent with efficiency gains. Bills rose $2m, raising potential consumer and market-power concerns. Net welfare requires further evidence.","При прежнем выпуске затраты упали на $1 млн — признак повышения эффективности. Счета выросли на $2 млн. Для вывода об общественном благосостоянии нужны дополнительные данные.","Bir xil xizmatda xarajat $1 mln kamaydi, bu samaradorlik belgisidir. To‘lov $2 mln oshdi; umumiy farovonlikni baholash uchun qo‘shimcha ma’lumot kerak."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-050","d":"hard","sec":190,"k":"D","en":"Market demand is Qd=180−3P and supply is Qs=30+2P. A licensing requirement restricts entry and effectively reduces supply to Qs=10+2P. What happens to equilibrium price and quantity, and what would removing that restriction restore, holding everything else fixed?","ru":"Рыночный спрос Qd=180−3P, предложение Qs=30+2P. Лицензирование ограничивает вход и уменьшает предложение до Qs=10+2P. Как изменяются равновесные цена и объём и что восстановит отмена ограничения при прочих равных?","uz":"Bozor talabi Qd=180−3P, taklif Qs=30+2P. Litsenziya talabi kirishni cheklab taklifni Qs=10+2P ga kamaytiradi. Muvozanat narx va miqdor qanday o‘zgaradi, boshqa shartlar o‘zgarmasa cheklovni bekor qilish nimani tiklaydi?","options_en":["Price falls by 4 and quantity rises by 12; repeal reverses these changes","Price rises by 10 and quantity falls by 30; repeal has no effect","Price rises by 4 and quantity stays constant; repeal lowers demand","Price rises by 4 and quantity falls by 12; repeal restores the earlier lower-price equilibrium"],"options_ru":["Цена падает на 4, объём растёт на 12; отмена обращает изменения","Цена растёт на 10, объём падает на 30; отмена не влияет","Цена растёт на 4, объём неизменен; отмена уменьшает спрос","Цена растёт на 4, объём падает на 12; отмена восстанавливает прежнее равновесие с меньшей ценой"],"options_uz":["Narx 4 ga kamayib, miqdor 12 ga oshadi; bekor qilish buni teskarilaydi","Narx 10 ga oshib, miqdor 30 ga kamayadi; bekor qilish ta’sirsiz","Narx 4 ga oshib, miqdor o‘zgarmaydi; bekor qilish talabni kamaytiradi","Narx 4 ga oshib, miqdor 12 ga kamayadi; bekor qilish avvalgi past narxli muvozanatni tiklaydi"],"why":["Without restriction 180−3P=30+2P gives P=30, Q=90. With restriction 180−3P=10+2P gives P=34, Q=78: price +4 and quantity −12. Repeal restores P=30, Q=90.","Без ограничения P=30, Q=90. При сдвиге предложения P=34, Q=78: цена +4, объём −12. Отмена возвращает исходное равновесие.","Cheklovsiz P=30, Q=90; cheklov bilan P=34, Q=78. Narx +4, miqdor −12. Bekor qilish avvalgi holatni tiklaydi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-052","d":"hard","sec":190,"k":"B","en":"A city proposes mandatory taxi-driver safety testing. The annual expected value of accidents avoided is $270,000. Drivers'' compliance costs total $90,000, enforcement costs $30,000, and the programme is expected to reduce service availability with an additional $60,000 social loss. Ignoring any other effects, what is estimated annual net social benefit?","ru":"Город предлагает обязательную проверку безопасности водителей такси. Ожидаемая годовая выгода от предотвращённых аварий $270 000. Соблюдение требований обойдётся водителям в $90 000, контроль — в $30 000; снижение доступности такси принесёт дополнительный общественный ущерб $60 000. Игнорируя другие эффекты, найдите ожидаемую годовую чистую общественную выгоду.","uz":"Shahar taksi haydovchilarining majburiy xavfsizlik sinovini taklif qilmoqda. Oldi olingan baxtsiz hodisalarning yillik kutilgan foydasi $270 000. Haydovchi moslashuv xarajati $90 000, nazorat $30 000, taksi xizmatining kamayishi esa qo‘shimcha $60 000 ijtimoiy zarar beradi. Boshqa ta’sirsiz yillik sof ijtimoiy foyda qancha?","options_en":["$270,000","$90,000","$150,000","−$90,000"],"options_ru":["$270 000","$90 000","$150 000","−$90 000"],"options_uz":["$270 000","$90 000","$150 000","−$90 000"],"why":["Net benefit =270,000−90,000−30,000−60,000=$90,000. Even when positive, the estimate depends on the reliability of all four values.","Чистая выгода 270 000−90 000−30 000−60 000=$90 000. Результат положительный, но зависит от обоснованности всех оценок.","Sof foyda 270 000−90 000−30 000−60 000=$90 000. Natija musbat, lekin to‘rt bahoning ishonchliligiga bog‘liq."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-053","d":"hard","sec":190,"k":"C","en":"A green-subsidy scheme pays each factory $500 on receiving a compliance certificate. A factory can genuinely comply at a cost of $600 or submit a false certificate without that cost. False claims are detected independently with probability 30% and incur a fine F, with no other consequences. Since both strategies receive the same $500 grant, what is the minimum fine that makes genuine compliance at least as profitable as a false claim?","ru":"Экологическая программа выдаёт заводу субсидию $500 после получения сертификата. Завод может реально выполнить требования за $600 или подать ложный сертификат без этих затрат. Обман независимо обнаруживается с вероятностью 30% и влечёт штраф F; других последствий нет. Поскольку оба варианта дают одинаковую субсидию $500, какой минимальный штраф сделает соблюдение не менее выгодным, чем обман?","uz":"Ekologik dastur sertifikat olgan zavodga $500 subsidiya beradi. Zavod talablarni haqiqatan bajarish uchun $600 sarflashi yoki bu xarajatsiz soxta sertifikat berishi mumkin. Soxtalik 30% ehtimol bilan aniqlanib F jarima solinadi, boshqa oqibat yo‘q. Ikkala yo‘l ham bir xil $500 subsidiya olsa, haqiqiy rioya qilishni soxtalikdan kam bo‘lmagan foydali qilish uchun eng kam jarima qancha?","options_en":["$600","$1,500","$2,000","$3,000"],"options_ru":["$600","$1 500","$2 000","$3 000"],"options_uz":["$600","$1500","$2000","$3000"],"why":["Compliance has additional private cost $600. False claiming has expected penalty 0.30×F. For compliance to be no worse, 0.30F≥600, so F≥$2,000. The $500 grant cancels because both strategies receive it.","Соблюдение дополнительно стоит $600, ложная заявка несёт ожидаемый штраф 0,30×F. Для сопоставимости 0,30F≥600, следовательно F≥$2 000. Субсидия $500 одинакова для двух вариантов и сокращается.","Haqiqiy rioya qilishning qo‘shimcha xarajati $600, soxta arizaning kutilgan jarimasi 0,30×F. 0,30F≥600 bo‘lsa, F≥$2000. $500 grant ikkala yo‘lda bir xil bo‘lgani uchun qisqaradi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-055","d":"hard","sec":200,"k":"C","en":"To meet an emission cap, two firms must jointly cut emissions by three tonnes. Firm A''s successive one-tonne abatement costs are $10, $20, $30; Firm B''s are $40, $50, $60. Initially A is required to cut one tonne and B two tonnes. With perfect permit trading and no transaction costs, which allocation minimises total abatement cost, and how much is saved compared with the initial assignment?","ru":"Чтобы соблюсти общий лимит выбросов, две фирмы должны совместно сократить загрязнение на три тонны. Затраты фирмы A на последовательные тонны снижения: $10, $20, $30; фирмы B: $40, $50, $60. Первоначально A обязана сократить одну тонну, B — две. При свободной торговле разрешениями и нулевых транзакционных затратах какое распределение минимизирует затраты и сколько экономит относительно исходного?","uz":"Umumiy emissiya chegarasi uchun ikki firma jami uch tonna chiqindini kamaytirishi kerak. A firmasida ketma-ket tonna xarajatlari $10, $20, $30, B da $40, $50, $60. Dastlab A bir tonna, B ikki tonna kamaytirishi shart. Ruxsatnomalar erkin savdo qilinsa va bitim xarajati nol bo‘lsa, qaysi taqsimot xarajatni minimallashtiradi va dastlabkiga nisbatan qancha tejaydi?","options_en":["A cuts one, B cuts two; savings $40","A cuts two, B cuts one; savings $0","A cuts three, B cuts zero; savings $40","A cuts zero, B cuts three; savings $40"],"options_ru":["A — одну, B — две; экономия $40","A — две, B — одну; экономия $0","A — три, B — ноль; экономия $40","A — ноль, B — три; экономия $40"],"options_uz":["A bir, B ikki tonna; tejam $40","A ikki, B bir tonna; tejam $0","A uch, B nol tonna; tejam $40","A nol, B uch tonna; tejam $40"],"why":["Initial abatement cost is $10+($40+$50)=$100. Cheapest three cuts are all at A: $10+$20+$30=$60, saving $40 while keeping the same total cap.","Исходные затраты $10+$40+$50=$100. Три самые дешёвые тонны сокращения — все у A: $10+$20+$30=$60. Экономия $40 при прежнем лимите.","Dastlab xarajat $10+$40+$50=$100. Eng arzon uch tonnani A kamaytiradi: $10+$20+$30=$60. Tejam $40, umumiy limit o‘zgarmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-056","d":"hard","sec":210,"k":"D","en":"A single large employer faces labour supply w=10+L, where L is employment and w is wage. Its marginal revenue product of labour is MRP=70−2L. Hiring an extra worker requires raising the wage for all workers. In the continuous monopsony model, what are monopsony employment and wage, compared with the competitive benchmark?","ru":"Единственный крупный работодатель сталкивается с предложением труда w=10+L, где L — занятость, w — зарплата. Предельная доходность труда MRP=70−2L. Для найма дополнительного работника нужно повысить зарплату всем. В непрерывной модели монопсонии найдите занятость и зарплату по сравнению с конкурентным ориентиром.","uz":"Yagona yirik ish beruvchi w=10+L mehnat taklifiga duch keladi, bunda L bandlik, w ish haqi. Mehnatning chegaraviy daromad mahsuloti MRP=70−2L. Yangi ishchi uchun hammaga ish haqi oshiriladi. Uzluksiz monopsoniya modelida bandlik va ish haqi raqobatli holatga nisbatan qanday?","options_en":["Monopsony L=20, w=30; competition L=15, w=25","Monopsony L=15, w=40; competition L=20, w=30","Monopsony L=15, w=30; competition L=20, w=40","Monopsony L=15, w=25; competition L=20, w=30"],"options_ru":["Монопсония L=20, w=30; конкуренция L=15, w=25","Монопсония L=15, w=40; конкуренция L=20, w=30","Монопсония L=15, w=30; конкуренция L=20, w=40","Монопсония L=15, w=25; конкуренция L=20, w=30"],"options_uz":["Monopsoniya L=20, w=30; raqobat L=15, w=25","Monopsoniya L=15, w=40; raqobat L=20, w=30","Monopsoniya L=15, w=30; raqobat L=20, w=40","Monopsoniya L=15, w=25; raqobat L=20, w=30"],"why":["Total wage bill is L(10+L); marginal expenditure ME=10+2L. Set ME=MRP: 10+2L=70−2L, L=15, w=25. Competitive MRP=w gives L=20, w=30.","Общие затраты на труд L(10+L), предельные ME=10+2L. При ME=MRP получаем L=15, w=25. В конкуренции MRP=w даёт L=20, w=30.","Jami ish haqi L(10+L), chegaraviy xarajat ME=10+2L. ME=MRP dan L=15, w=25. Raqobatda MRP=w dan L=20, w=30."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-058","d":"hard","sec":185,"k":"B","en":"A school has exactly 45 tutoring hours. Ten students in Group X each need three hours to reach a minimum standard; thirty in Group Y each need one hour. A student reaches the standard only after receiving all required hours. If the sole goal is to maximise the number who reach the standard, which allocation is optimal?","ru":"У школы ровно 45 часов дополнительных занятий. Каждому из десяти учеников группы X нужно по три часа для достижения минимума, а каждому из тридцати учеников группы Y — по одному. Ученик достигает минимума только после получения всей необходимой помощи. Если единственная цель — максимальное число достигших минимума, какое распределение оптимально?","uz":"Maktabda aynan 45 ta qo‘shimcha dars soati bor. X guruhidagi 10 o‘quvchining har biriga standartga yetish uchun 3 soat, Y dagi 30 o‘quvchining har biriga 1 soat kerak. O‘quvchi faqat barcha kerakli soat olgach standartga yetadi. Maqsad faqat standartga yetganlar sonini ko‘paytirish bo‘lsa, qaysi taqsimot optimal?","options_en":["Give 1.125 hours to all 40 students; 40 reach the standard","Give 30 hours to Y and 15 hours to five X students; 35 reach the standard","Give 30 hours to all X, then divide 15 hours among Y; 40 reach the standard","Give each X three hours; the remaining 15 hours cannot be used"],"options_ru":["Раздать всем 40 по 1,125 часа; стандарт достигнут все 40","Выделить 30 часов группе Y и 15 часов пяти ученикам X; достигнут стандарт 35","Выделить 30 часов всем X и разделить оставшиеся 15 между Y; стандарт достигнут 40","Выделить каждому X по 3 часа; оставшиеся 15 часов бесполезны"],"options_uz":["40 o‘quvchiga 1,125 soatdan; 40 tasi standartga yetadi","Y guruhiga 30 soat, X dagi 5 o‘quvchiga 15 soat; 35 tasi standartga yetadi","X ga 30 soat, qolgan 15 soat Y o‘rtasida; 40 tasi standartga yetadi","X dagilarga 3 soatdan; qolgan 15 soat ishlatilmaydi"],"why":["Cover all 30 one-hour needs first (30 hours), then use 15 hours for five three-hour needs. That yields 35 complete students; evenly spreading hours would leave many short.","Сначала удовлетворяются потребности всех 30 учеников Y (30 часов), затем 15 часов — пяти ученикам X. Итого 35 достигают стандарта; равное дробление не гарантирует результата.","Avval Y dagi 30 o‘quvchiga 30 soat, qolgan 15 soat X dagi 5 o‘quvchiga beriladi. 35 tasi standartga yetadi; teng bo‘lib tarqatish ko‘pchilikni yetkaza olmaydi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-062","d":"hard","sec":190,"k":"A","en":"A low-income worker earns an additional $300 per month. Income tax is 20% of extra earnings, means-tested benefits fall by $0.60 per extra $1, and commuting expenses rise by $40. What is the worker''s extra disposable money after all three effects, and what does this illustrate?","ru":"Низкооплачиваемый работник зарабатывает дополнительно $300 в месяц. Подоходный налог составляет 20% дополнительного заработка, адресные пособия сокращаются на $0,60 за каждый дополнительный доллар, транспортные расходы растут на $40. Сколько дополнительных свободных средств остаётся и какую проблему это иллюстрирует?","uz":"Kam daromadli ishchi oyiga qo‘shimcha $300 ishlab topadi. Qo‘shimcha daromaddan 20% soliq olinadi, manzilli nafaqa har $1 uchun $0,60 ga kamayadi va yo‘l xarajati $40 ga oshadi. Oxirida qancha qo‘shimcha erkin mablag‘ qoladi va bu nimani ko‘rsatadi?","options_en":["$20; a strong poverty-trap disincentive","$60; no work disincentive","$120; the full marginal tax rate is only 20%","$300; transfers and travel costs are irrelevant"],"options_ru":["$20; сильный стимул не увеличивать заработок из-за ловушки бедности","$60; препятствий к дополнительной работе нет","$120; предельная совокупная ставка лишь 20%","$300; пособия и транспорт несущественны"],"options_uz":["$20; kambag‘allik tuzog‘i tufayli mehnatga kuchli salbiy rag‘bat","$60; ishlashga to‘sqinlik yo‘q","$120; umumiy chegaraviy soliq atigi 20%","$300; nafaqa va yo‘l xarajati ahamiyatsiz"],"why":["Extra pay $300 − tax $60 − benefit withdrawal $180 − commute $40 = $20. Only $20 of $300 remains, signalling a poverty trap.","Дополнительный доход $300 минус налог $60, потеря пособия $180 и дорога $40 оставляет $20. Большая часть заработка не увеличивает располагаемые ресурсы.","Qo‘shimcha $300 dan $60 soliq, $180 nafaqa yo‘qotish va $40 yo‘l xarajati ayirilsa $20 qoladi; kambag‘allik tuzog‘i."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-065","d":"hard","sec":185,"k":"C","en":"A city reimburses a taxi operator for 90% of its verified operating losses. The operator could spend $200 on an efficiency review that would certainly reduce operating costs by $1,000 without changing service. Assume reimbursement adjusts dollar for dollar to cost changes. What is the private net benefit to the operator from the review, and the net resource benefit to society?","ru":"Город возмещает оператору такси 90% подтверждённых операционных убытков. Оператор может потратить $200 на проверку эффективности, которая гарантированно снизит операционные затраты на $1 000 без изменения услуги. Возмещение автоматически меняется вместе с затратами. Какова частная чистая выгода оператора от проверки и чистая ресурсная выгода общества?","uz":"Shahar taksi operatorining tasdiqlangan operatsion zararining 90% ini qoplaydi. Operator $200 sarflab xizmatni o‘zgartirmasdan xarajatni albatta $1000 kamaytiradigan samaradorlik tekshiruvini o‘tkazishi mumkin. Qoplama xarajat bilan birga o‘zgaradi. Operatorning xususiy sof foydasi va jamiyat resurs foydasi qancha?","options_en":["Private +$800; social −$100","Private +$100; social +$1,000","Private −$100; social +$800","Private +$800; social +$100"],"options_ru":["Частная +$800; общественная −$100","Частная +$100; общественная +$1 000","Частная −$100; общественная +$800","Частная +$800; общественная +$100"],"options_uz":["Xususiy +$800; ijtimoiy −$100","Xususiy +$100; ijtimoiy +$1000","Xususiy −$100; ijtimoiy +$800","Xususiy +$800; ijtimoiy +$100"],"why":["Reimbursement falls $900 when operating cost falls $1,000. The operator keeps only $100 of savings but pays $200, net −$100. Society saves $1,000 resources less review cost $200, net +$800.","При экономии $1 000 возмещение уменьшается на $900, оператор сохраняет лишь $100, но платит $200: чистая частная выгода −$100. Обществу остаётся $1 000−$200=+$800.","Xarajat $1000 kamayganda qoplama $900 kamayadi, operator $100 tejab $200 sarflaydi: sof −$100. Jamiyat $1000−$200=+$800 resurs tejaydi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-067","d":"hard","sec":195,"k":"D","en":"In a competitive labour market, demand is Ld=100−2w and supply Ls=10+w, where w is hourly wage. A union enforces a wage of $35 without shifting either curve. Relative to the original equilibrium, what happens to employment, and how many willing workers are not hired at that wage?","ru":"На конкурентном рынке труда спрос Ld=100−2w, предложение Ls=10+w, где w — почасовая зарплата. Профсоюз добивается ставки $35, не сдвигая кривые. Как меняется занятость относительно прежнего равновесия и сколько готовых работать людей не находят работу при этой ставке?","uz":"Raqobatli mehnat bozorida talab Ld=100−2w, taklif Ls=10+w, bunda w soatlik ish haqi. Kasaba uyushmasi egri chiziqlarni o‘zgartirmasdan $35 stavkani belgilaydi. Avvalgi muvozanatga nisbatan bandlik qanday o‘zgaradi va shu stavkada nechta ish izlovchi yollanmaydi?","options_en":["Employment rises from 40 to 45; unemployment zero","Employment stays 40; 15 unemployed","Employment falls from 40 to 30; unemployment five","Employment falls from 40 to 30; 15 willing workers are not hired"],"options_ru":["Занятость растёт с 40 до 45; безработицы нет","Занятость остаётся 40; не наняты 15","Занятость падает с 40 до 30; не наняты пятеро","Занятость падает с 40 до 30; не наняты 15 желающих"],"options_uz":["Bandlik 40 dan 45 ga oshadi; ishsizlik yo‘q","Bandlik 40 bo‘lib qoladi; 15 kishi ishsiz","Bandlik 40 dan 30 ga tushadi; 5 kishi yollanmaydi","Bandlik 40 dan 30 ga tushadi; 15 ish istovchi yollanmaydi"],"why":["Equilibrium 100−2w=10+w gives w=30, L=40. At wage 35, demand=30 and supply=45, so employment=30 and excess labour supply=15.","Равновесие w=30, L=40. При w=35 спрос на труд 30, предложение 45. Занятость 30, избыточное предложение труда 15.","Muvozanatda w=30, L=40. w=35 da talab 30, taklif 45. Bandlik 30, ortiqcha mehnat taklifi 15."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-068","d":"hard","sec":195,"k":"B","en":"A river-polluting firm can avoid causing $180 of verified harm to downstream fishers by spending $110 on a filter. Monitoring and negotiating enforceable compensation would cost another $20. No other effects occur. What is the maximum net joint gain from reaching an agreement to install the filter, and which obstacle could prevent it?","ru":"Предприятие загрязняет реку, причиняя рыбакам ниже по течению подтверждённый ущерб $180. Фильтр стоимостью $110 предотвращает ущерб; контроль и переговоры о юридически защищённой компенсации стоят ещё $20. Других эффектов нет. Каков максимальный общий чистый выигрыш от соглашения установить фильтр и что может помешать?","uz":"Korxona daryoni ifloslantirib, quyi oqimdagi baliqchilarga tasdiqlangan $180 zarar yetkazadi. $110 lik filtr zararni oldini oladi, huquqiy kuchga ega kelishuvni nazorat qilish va muzokara yana $20 turadi. Boshqa ta’sir yo‘q. Filtr o‘rnatish kelishuvining maksimal jami sof foydasi qancha va unga nima to‘sqinlik qilishi mumkin?","options_en":["$70; no negotiation costs can ever arise","$50; high transaction or enforcement costs could destroy the bargaining surplus","$180; the filter cost is a pure transfer","−$50; continuing pollution is necessarily optimal"],"options_ru":["$70; переговорные издержки никогда не возникают","$50; высокие издержки сделки или защиты прав могут уничтожить выгоду переговоров","$180; затраты на фильтр — лишь трансферт","−$50; продолжать загрязнение обязательно эффективно"],"options_uz":["$70; muzokara xarajati hech qachon bo‘lmaydi","$50; yuqori bitim yoki huquqni ta’minlash xarajatlari kelishuv foydasini yo‘q qilishi mumkin","$180; filtr xarajati faqat transfert","−$50; ifloslantirishni davom ettirish albatta optimal"],"why":["The avoided harm of $180 minus filter cost $110 and transaction cost $20 gives $50 net surplus. Larger transaction costs can impede a mutually beneficial agreement.","Предотвращённый ущерб $180 минус фильтр $110 и издержки соглашения $20 даёт $50 чистой выгоды. Более высокие издержки могут сделать переговоры невыгодными.","Oldi olingan $180 zarar minus $110 filtr va $20 bitim xarajati = $50 sof foyda. Yuqori bitim xarajatlari kelishuvga to‘sqinlik qiladi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-034","d":"medium","sec":155,"k":"C","en":"A pension programme changes from voluntary sign-up to automatic enrolment with a simple, free opt-out. Contribution rates, investment options and wages remain unchanged. Which explanation best describes a possible increase in enrolment?","ru":"Пенсионная программа переходит от добровольной подачи заявления к автоматическому подключению с простым и бесплатным отказом. Размер взносов, варианты инвестиций и зарплаты неизменны. Что лучше объясняет возможный рост участия?","uz":"Pensiya dasturi ixtiyoriy ro‘yxatdan o‘tishdan bepul va oson rad etish huquqi bilan avtomatik qo‘shishga o‘tadi. Badal, investitsiya tanlovi va ish haqi o‘zgarmaydi. Ishtirok oshishini qaysi omil yaxshiroq tushuntiradi?","options_en":["The legal right to opt out is removed","The government directly raises every worker''s income","A changed default can exploit inertia while preserving choice","The opportunity cost of all consumption becomes zero"],"options_ru":["Право отказаться отменяется","Государство непосредственно повышает доход всех работников","Изменение варианта по умолчанию учитывает инерцию выбора, сохраняя свободу решения","Альтернативная стоимость любого потребления становится нулевой"],"options_uz":["Rad etish huquqi bekor qilinadi","Davlat barcha ishchilar daromadini bevosita oshiradi","Standart tanlov o‘zgarib, odatiy inersiyaga ta’sir qiladi, ammo tanlash erkinligi saqlanadi","Har qanday iste’molning muqobil qiymati nolga tushadi"],"why":["Automatic enrolment changes the default, so some inert workers remain signed up, but the opt-out preserves freedom. No wage or price change is needed.","Автоматическое подключение меняет настройку по умолчанию: часть пассивных работников остаётся участниками при сохранении права отказа.","Avtomatik qo‘shilish standart tanlovni o‘zgartiradi, ayrim passiv ishchilar qatnashib qoladi, rad etish erkinligi saqlanadi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-051","d":"medium","sec":145,"k":"B","en":"A remote village lacks a private clinic because a small population makes user fees insufficient to cover fixed operating costs. The government funds a local clinic providing essential vaccinations. Which pair correctly describes the access problem and policy response?","ru":"В отдалённой деревне нет частной клиники: из-за малочисленности населения платежи пациентов не покрывают постоянные расходы. Государство финансирует местную клинику для базовой вакцинации. Какая пара верно описывает проблему доступности и решение?","uz":"Olis qishloqda xususiy klinika yo‘q, chunki aholi kam va bemor to‘lovi doimiy xarajatni qoplamaydi. Davlat zarur emlash uchun mahalliy klinikani moliyalashtiradi. Kirish muammosi va siyosiy javobning to‘g‘ri juftligi qaysi?","options_en":["Excess private competition; export subsidy","Low commercial viability and geographic access; direct public provision","A binding export quota; currency intervention","Excessively high private vaccination demand; price ceiling"],"options_ru":["Избыточная частная конкуренция; экспортная субсидия","Низкая коммерческая окупаемость и территориальный барьер; прямое государственное предоставление","Ограничение экспорта; валютная интервенция","Избыточный частный спрос на прививки; потолок цен"],"options_uz":["Ortiqcha xususiy raqobat; eksport subsidiyasi","Tijoriy rentabellik pastligi va hududiy to‘siq; davlatning bevosita xizmat ko‘rsatishi","Eksport kvotasi; valuta aralashuvi","Ortiqcha emlash talabi; narx chegarasi"],"why":["Low-density demand may not cover clinic fixed costs despite medical needs. Public provision directly finances local access, although efficiency still requires evaluation.","Малый рынок может не покрывать постоянные затраты клиники. Государственное предоставление расширяет территориальную доступность, однако эффективность требует оценки.","Aholi kam bo‘lganda klinika doimiy xarajatlarini qoplash qiyin. Davlat xizmati hududiy kirishni kengaytiradi, lekin samaradorlik baholanishi kerak."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-054","d":"medium","sec":160,"k":"D","en":"A firm''s labour supply schedule is Ls=5+2w, where L is worker-hours and w is hourly pay. The firm raises the offered wage from $10 to $13, and workers'' preferences do not shift. What is the modelled change in worker-hours supplied, and is it a movement along or shift of the supply curve?","ru":"Предложение труда фирме задано Ls=5+2w, где L — человеко-часы, w — почасовая оплата. Фирма повышает ставку с $10 до $13, предпочтения работников не меняются. На сколько увеличатся предлагаемые часы и будет ли это движение вдоль кривой или её сдвиг?","uz":"Firmaga mehnat taklifi Ls=5+2w, bunda L ishchi-soat, w soatlik ish haqi. Firma ish haqini $10 dan $13 ga oshiradi, ishchilar afzalligi o‘zgarmaydi. Taklif etilgan soatlar qanchaga o‘zgaradi va bu egri chiziq bo‘ylab harakatmi yoki siljishmi?","options_en":["+3 hours; rightward shift","−6 hours; movement along"," +6 hours; rightward shift"," +6 hours; movement along existing labour supply"],"options_ru":["+3 часа; сдвиг вправо","−6 часов; движение вдоль"," +6 часов; сдвиг вправо"," +6 часов; движение вдоль существующей кривой предложения труда"],"options_uz":["+3 soat; o‘ngga siljish","−6 soat; chiziq bo‘ylab harakat"," +6 soat; o‘ngga siljish"," +6 soat; mavjud mehnat taklifi chizig‘i bo‘ylab harakat"],"why":["At w=10, L=25; at w=13, L=31, a rise of six hours. Since only wage changes, the movement is along the original supply curve.","При w=10 предложение 25 часов, при w=13 — 31; увеличение на 6 часов. Меняется только ставка, поэтому движение вдоль прежней кривой.","w=10 da L=25, w=13 da L=31, 6 soat ko‘payadi. Faqat ish haqi o‘zgargani uchun mavjud egri chiziq bo‘ylab harakat."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-061","d":"medium","sec":155,"k":"C","en":"Solar-panel orders rise, increasing installers'' expected marginal revenue product, while a vocational college simultaneously qualifies more electricians. In a competitive labour market, what can be predicted about employment and wages if both labour demand and labour supply shift right?","ru":"Заказы на солнечные панели растут, увеличивая ожидаемую MRP установщиков. Одновременно профессиональный колледж выпускает больше квалифицированных электриков. На конкурентном рынке труда спрос и предложение труда сдвигаются вправо. Каков наиболее обоснованный прогноз занятости и зарплаты?","uz":"Quyosh panellari buyurtmalari oshib, o‘rnatuvchilar MRP sini oshiradi. Shu payt kasb kolleji ko‘proq elektrchi tayyorlaydi. Raqobatli mehnat bozorida talab ham, taklif ham o‘ngga siljiydi. Bandlik va ish haqi haqida qanday ishonchli xulosa qilish mumkin?","options_en":["Employment falls and wage necessarily rises","Employment unchanged and wage necessarily falls","Employment rises, while the wage change is uncertain without shift magnitudes","Both employment and wages must fall"],"options_ru":["Занятость падает, зарплата обязательно растёт","Занятость неизменна, зарплата обязательно падает","Занятость растёт, изменение зарплаты неоднозначно без размеров сдвигов","Занятость и зарплата обязательно падают"],"options_uz":["Bandlik kamayadi, ish haqi albatta oshadi","Bandlik o‘zgarmaydi, ish haqi albatta tushadi","Bandlik oshadi, ish haqi yo‘nalishi siljish kattaligiga bog‘liq","Bandlik va ish haqi albatta kamayadi"],"why":["Demand expansion and supply expansion both raise equilibrium labour quantity under usual slopes. Their opposing wage effects leave the wage direction indeterminate.","Рост спроса и предложения труда повышает равновесную занятость при обычных наклонах кривых. Влияние на зарплату направлено противоположно.","Talab va taklifning kengayishi odatdagi egri chiziqlarda bandlikni oshiradi. Ish haqiga ta’sirlari qarama-qarshi, natija noaniq."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-063","d":"medium","sec":150,"k":"B","en":"Applicants to an occupation must now finish two years of compulsory training and obtain a licence. Existing qualified workers keep practising; employer demand and wages are initially fixed. Which short-run effect is most plausible?","ru":"Для входа в профессию теперь нужны двухлетнее обязательное обучение и лицензия. Уже квалифицированные работники продолжают работать; спрос работодателей и зарплата первоначально неизменны. Какой краткосрочный эффект наиболее вероятен?","uz":"Kasbga kirish uchun endi ikki yillik majburiy ta’lim va litsenziya kerak. Oldindan malakali ishchilar ishlashda davom etadi, ish beruvchi talabi va ish haqi dastlab o‘zgarmaydi. Qisqa muddatli eng ehtimolli ta’sir qanday?","options_en":["More newly qualified entrants can work immediately","Fewer new entrants can supply labour immediately, creating a temporary entry barrier","All existing workers lose legal jobs instantly","Product demand necessarily falls by the same percentage"],"options_ru":["Больше новых специалистов сразу приступают к работе","Меньше новичков могут немедленно предложить труд; возникает временный барьер входа","Все прежние работники немедленно теряют работу","Спрос на продукт обязательно падает на тот же процент"],"options_uz":["Yangi mutaxassislar darhol ko‘proq ishlaydi","Yangi kiruvchilar darhol kamroq mehnat taklif qiladi, vaqtinchalik kirish to‘sig‘i paydo bo‘ladi","Barcha amaldagi ishchilar darhol ishini yo‘qotadi","Mahsulot talabi albatta aynan shuncha foiz tushadi"],"why":["The new training and licensing delay affects prospective entrants rather than automatically removing existing licensed workers, tightening short-run new supply.","Новые требования задерживают вход новичков, не увольняя автоматически уже квалифицированных работников. Краткосрочное предложение новых работников сокращается.","Yangi talablar bo‘lajak ishchilarning kirishini kechiktiradi, mavjud malakalilarni avtomatik chetlatmaydi. Qisqa muddatli yangi taklif kamayadi."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-066","d":"medium","sec":155,"k":"D","en":"A country has 1,000 households, of which 200 fall below a defined poverty threshold. A fixed $200,000 transfer budget can be given equally to all households or only to those 200 households. What is the grant per household under each policy and the trade-off?","ru":"В стране 1 000 домохозяйств, из которых 200 находятся ниже установленной черты бедности. Бюджет трансфертов $200 000 можно равномерно распределить всем либо направить только этим 200 семьям. Какова выплата на домохозяйство при каждой схеме и в чём компромисс?","uz":"Mamlakatda 1000 xonadon bor, ulardan 200 tasi belgilangan kambag‘allik chegarasidan past. $200 000 transfert budjetini hammaga teng yoki faqat shu 200 xonadonga berish mumkin. Har biriga qanchadan beriladi va qanday muvozanatli tanlov mavjud?","options_en":["Universal $1,000; targeted $200; targeting is always costless","Universal $200; targeted $200; coverage is identical","Universal $200; targeted $1,000; universal transfers necessarily eliminate poverty","Universal $200; targeted $1,000; targeting concentrates help but needs eligibility decisions"],"options_ru":["Всем $1 000; адресно $200; адресность всегда бесплатна","Всем $200; адресно $200; охват идентичен","Всем $200; адресно $1 000; универсальная схема обязательно устраняет бедность","Всем $200; адресно $1 000; адресная помощь концентрирует поддержку, но требует отбора"],"options_uz":["Umumiy $1000; manzilli $200; tanlash har doim bepul","Umumiy $200; manzilli $200; qamrov bir xil","Umumiy $200; manzilli $1000; universal yordam kambag‘allikni albatta yo‘q qiladi","Umumiy $200; manzilli $1000; manzillilik ko‘makni jamlaydi, lekin tanlov talab qiladi"],"why":["Universal payment is 200,000/1,000=$200 each; targeted is 200,000/200=$1,000 each. Targeting supports a smaller group more intensely but creates eligibility and exclusion risks.","Универсальная выплата $200 каждому, адресная — $1 000 на нуждающуюся семью. Адресность усиливает помощь, но требует отбора и несёт риск исключения.","Universal to‘lov har biriga $200, manzilli esa $1000. Manzillilik yordamni jamlaydi, ammo moslikni tekshirish va kimnidir chetda qoldirish xavfi bor."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-069","d":"medium","sec":155,"k":"A","en":"A national absolute poverty line is $700 per month; the relative poverty threshold is 60% of a $1,500 median disposable income. A household earns $800 per month. Under these definitions, how is its poverty status classified?","ru":"Абсолютная черта бедности равна $700 в месяц; относительный порог установлен на уровне 60% медианного располагаемого дохода $1 500. Доход семьи $800 в месяц. Как классифицируется её положение по обоим определениям?","uz":"Mutlaq kambag‘allik chegarasi oyiga $700, nisbiy kambag‘allik chegarasi esa median ixtiyordagi daromad $1500 ning 60% i. Bir xonadon oyiga $800 topadi. Ushbu ikki ta’rif bo‘yicha uning holati qanday?","options_en":["Above the absolute line but below the $900 relative threshold","Below the absolute line but above the relative threshold","Below both lines because $800 is less than $1,500","Above both lines because relative poverty cannot exceed absolute poverty"],"options_ru":["Выше абсолютной черты, но ниже относительного порога $900","Ниже абсолютной черты, но выше относительного порога","Ниже обеих, поскольку $800 меньше $1 500","Выше обеих, потому что относительный порог не может быть выше абсолютного"],"options_uz":["Mutlaq chegaradan yuqori, ammo $900 nisbiy chegaradan past","Mutlaq chegaradan past, nisbiy chegaradan yuqori","Ikkalasidan past, chunki $800 $1500 dan kam","Ikkalasidan yuqori, chunki nisbiy chegara mutlaqdan katta bo‘lmaydi"],"why":["Relative threshold =0.60×$1,500=$900. Income $800 is above the absolute $700 line but below the relative $900 line.","Относительный порог 0,60×$1 500=$900. Доход $800 выше абсолютной черты $700, но ниже относительной $900.","Nisbiy chegara 0,60×$1500=$900. $800 daromad mutlaq $700 dan yuqori, nisbiy $900 dan past."]},{"ref":"EC9708:G2:EC9708-G2-T5-P-070","d":"medium","sec":160,"k":"C","en":"A retirement app tests automatic enrolment with easy opt-out. Savings participation rises from 40% to 70%, but it provides no information on contribution amounts or whether users later remain enrolled. Which evaluation is best supported?","ru":"Приложение накоплений на пенсию проверяет автоматическое подключение с простым отказом. Доля участников выросла с 40% до 70%, но данных о суммах взносов и дальнейшей устойчивости участия нет. Какой вывод наиболее обоснован?","uz":"Pensiya jamg‘armasi ilovasi oson rad etish bilan avtomatik qo‘shilishni sinaydi. Ishtirok 40% dan 70% ga oshdi, ammo badal miqdori va keyingi davomiylik haqida ma’lumot yo‘q. Qaysi xulosa asosli?","options_en":["Retirement wealth certainly increased by 75% for every user","The change proves every user prefers to save more","A default can affect initial participation, but long-run savings outcomes require more evidence","Automatic enrolment has removed every financial constraint on saving"],"options_ru":["Пенсионное богатство каждого пользователя обязательно выросло на 75%","Изменение доказывает желание каждого больше сберегать","Настройка по умолчанию влияет на первоначальное участие, но долгосрочные сбережения требуют дополнительных данных","Автоматическое подключение устранило все финансовые ограничения"],"options_uz":["Har foydalanuvchining pensiya boyligi albatta 75% oshdi","Har bir foydalanuvchi ko‘proq jamg‘arishni xohlagani isbotlandi","Standart tanlov boshlang‘ich ishtirokka ta’sir qiladi, ammo uzoq muddatli natija uchun qo‘shimcha dalil kerak","Avtomatik qo‘shilish barcha moliyaviy cheklovni yo‘q qildi"],"why":["Initial participation rose by 30 percentage points, consistent with a default effect. Contribution levels, persistence and actual retirement outcomes were not measured.","Первоначальное участие выросло на 30 процентных пунктов, что согласуется с влиянием варианта по умолчанию. Размеры взносов и долгосрочные результаты неизвестны.","Dastlabki ishtirok 30 foiz punktga oshdi, bu standart tanlov ta’siriga mos. Badal miqdori va uzoq muddatli natija noma’lum."]}]'::jsonb;
  item jsonb; v_old bigint; v_new bigint; v_pool bigint; v_order int; v_count int;
  v_correct text; v_i int; v_why_en text; v_why_ru text; v_why_uz text; v_old_key text;
  v_saved_answers int;
BEGIN
  IF jsonb_array_length(payload) <> 28 THEN RAISE EXCEPTION 'expected_28_replacements'; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l
    JOIN public.practice_pools p ON p.id=l.pool_id WHERE p.subject_id=7 AND p.tour_no=5 AND l.is_active;
  IF v_count <> 70 THEN RAISE EXCEPTION 'T5_pool_not_70_before: %',v_count; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(payload)
  LOOP
    v_old_key := item->>'ref'; v_correct := item->>'k';
    IF jsonb_array_length(item->'options_en')<>4 OR jsonb_array_length(item->'options_ru')<>4 OR jsonb_array_length(item->'options_uz')<>4 THEN
      RAISE EXCEPTION 'four_options_required: %',v_old_key;
    END IF;
    IF v_correct NOT IN ('A','B','C','D') OR item->>'d' NOT IN ('medium','hard') THEN RAISE EXCEPTION 'invalid_authoring: %',v_old_key; END IF;
    SELECT q.id INTO STRICT v_old FROM public.questions q WHERE q.subject_id=7 AND q.book_ref=v_old_key;
    SELECT count(*) INTO v_saved_answers FROM public.practice_answers a WHERE a.question_id=v_old;
    IF v_saved_answers > 0 THEN RAISE EXCEPTION 'review_history_bearing_question_before_replacement: %',v_old_key; END IF;
    SELECT l.pool_id,l.order_no INTO STRICT v_pool,v_order FROM public.practice_pool_questions l
      JOIN public.practice_pools p ON p.id=l.pool_id
      WHERE l.question_id=v_old AND l.is_active AND p.subject_id=7 AND p.tour_no=5;
    SELECT id INTO v_new FROM public.questions WHERE subject_id=7 AND book_ref=v_old_key||'-V2';
    IF v_new IS NOT NULL THEN RAISE EXCEPTION 'already_exists: %',v_old_key; END IF;
    v_i := ascii(v_correct)-64;
    v_why_en := item->'why'->>0; v_why_ru := item->'why'->>1; v_why_uz := item->'why'->>2;
    INSERT INTO public.questions (
      subject_id,topic,subtopic,difficulty,qtype,
      question_text,options_text,correct_answer,explanation,image_url,is_active,
      question_text_ru,question_text_uz,question_text_en,
      options_text_ru,options_text_uz,options_text_en,
      explanation_ru,explanation_uz,explanation_en,
      book_ref,time_limit_sec,quality_flag,quality_status
    )
    SELECT
      src.subject_id,src.topic,src.subtopic,item->>'d','mcq',
      item->>'en',(item->'options_en')::text,v_correct,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      NULL,true,item->>'ru',item->>'uz',item->>'en',
      (item->'options_ru')::text,(item->'options_uz')::text,(item->'options_en')::text,
      'Правильный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nПочему: '||v_why_ru,
      'To‘g‘ri javob: '||(item->'options_uz'->>(v_i-1))||E'\nSabab: '||v_why_uz,
      'Correct answer: '||(item->'options_en'->>(v_i-1))||E'\nWhy: '||v_why_en,
      v_old_key||'-V2',(item->>'sec')::int,src.quality_flag,'published'
    FROM public.questions src WHERE src.id=v_old
    RETURNING id INTO v_new;
    UPDATE public.practice_pool_questions SET is_active=false
      WHERE pool_id=v_pool AND question_id=v_old AND is_active;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count<>1 THEN RAISE EXCEPTION 'old_link_not_one: %',v_old_key; END IF;
    INSERT INTO public.practice_pool_questions (pool_id,question_id,order_no,is_active)
      VALUES (v_pool,v_new,v_order,true);
    INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason)
      VALUES(v_old,v_new,'replacement','Economics Gen2: actual editorial difficulty upgrade, T5 governed practice, originals retained');
    FOR v_i IN 1..4 LOOP
      INSERT INTO public.question_answer_diagnostics(
        question_id,answer_kind,answer_key,answer_value,is_correct,
        mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,
        next_action_ru,next_action_uz,next_action_en,rule_json,quality_status
      )
      SELECT v_new,'mcq_option',chr(64+v_i),NULL,(chr(64+v_i)=v_correct),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'multi_step_economic_reasoning' END,
        src.subtopic,
        'Выбранный ответ: '||(item->'options_ru'->>(v_i-1))||E'\nОбъяснение: '||v_why_ru||E'\nПравильный ответ: '||(item->'options_ru'->>(ascii(v_correct)-65)),
        'Tanlangan javob: '||(item->'options_uz'->>(v_i-1))||E'\nIzoh: '||v_why_uz||E'\nTo‘g‘ri javob: '||(item->'options_uz'->>(ascii(v_correct)-65)),
        'Selected answer: '||(item->'options_en'->>(v_i-1))||E'\nReason: '||v_why_en||E'\nCorrect answer: '||(item->'options_en'->>(ascii(v_correct)-65)),
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Повторите метод решения и проверьте каждый шаг.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Yechim usulini takrorlang va har bir bosqichni tekshiring.' END,
        CASE WHEN chr(64+v_i)=v_correct THEN NULL ELSE 'Review the method and check each step.' END,
        jsonb_build_object('diagnostic_code','EC9708_G2_T5P'||substring(v_old_key from 'P-([0-9]{3})')||'_V2_'||chr(64+v_i)),
        'published'
      FROM public.questions src WHERE src.id=v_old;
    END LOOP;
  END LOOP;
  -- Existing unchanged T5 items receive academically reviewed metadata, not fabricated all-medium labels.
  UPDATE public.questions q SET difficulty=CASE
    WHEN right(q.book_ref,3) IN ('001','004','005','006','011','013','014','016','018','020','022','023','025','026','028','030','031','038','044','049','057','064') THEN 'medium'
    ELSE 'easy' END
    WHERE q.subject_id=7 AND q.book_ref ~ '^EC9708:G2:EC9708-G2-T5-P-[0-9]{3}$'
    AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(payload) j WHERE j->>'ref'=q.book_ref);
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF v_count<>42 THEN RAISE EXCEPTION 'unchanged_count_expected42: %',v_count; END IF;
  SELECT count(*) INTO v_count FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    WHERE p.subject_id=7 AND p.tour_no=5 AND l.is_active;
  IF v_count<>70 THEN RAISE EXCEPTION 'active_pool_not70_after: %',v_count; END IF;
  IF EXISTS (
    SELECT 1 FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
       JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=5 AND l.is_active
    GROUP BY 1 HAVING count(*)<>70
  ) THEN RAISE EXCEPTION 'pool_count_inconsistent'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=5 AND l.is_active AND q.difficulty='easy') <> 20
    THEN RAISE EXCEPTION 'difficulty_easy_not20'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=5 AND l.is_active AND q.difficulty='medium') <> 30
    THEN RAISE EXCEPTION 'difficulty_medium_not30'; END IF;
  IF (SELECT count(*) FROM public.practice_pool_questions l JOIN public.practice_pools p ON p.id=l.pool_id
    JOIN public.questions q ON q.id=l.question_id
    WHERE p.subject_id=7 AND p.tour_no=5 AND l.is_active AND q.difficulty='hard') <> 20
    THEN RAISE EXCEPTION 'difficulty_hard_not20'; END IF;
END $reb$;
COMMIT;
